$A.componentService.addComponentClass("markup://flexipage:runtimeComponent",function() {
return {
  "meta":{
    "name":"flexipage$runtimeComponent",
    "extends":"markup://aura:component",
    "imports":{
      "formula":"markup://formula:formulaLibrary",
      "componentTracker":"markup://instrumentation:componentTracker"
    }
  },
  "controller":{
    "init":function(cmp, event, helper) {
        var cdr = cmp.get('v.componentInfoDefRef') || [];
        var cdrClone = JSON.parse(JSON.stringify(cdr));
        cmp.set('v._localComponentInfoDefRef', cdrClone);
        helper.evaluateComponentRule(cmp, false);
    },
    "refresh":function(cmp, event, helper) {
        helper.evaluateComponentRule(cmp, true);
    },
    "update":function(cmp, event, helper) {
        if (event.getParam('changeType') !== 'LOADED') {
            helper.evaluateComponentRule(cmp, false);
        }
    }
  },
  "helper":{
    "initialize":function(cmp, isRefresh) {
        var helper = this;
        var cdr = helper.getComponentInfoDefRef(cmp) || [];
        var body = cmp.get('v.body') || [];
        var updateComponentContent = cmp.get('v.updateComponentContent') || false;

        if ((isRefresh || body.length === 0 || updateComponentContent)) {
            var component = body[0];
            if (component && isRefresh && updateComponentContent === false) {
                helper.refresh(cmp, cdr);
            } else {
                helper.createConcreteComponent(cmp, cdr);
            }
        }
    },
    "createConcreteComponent":function(cmp, infoOfComponent) {
        if (!cmp.isValid()){
            return;
        }
        var helper = this;
        var config = infoOfComponent[0];
        try {
            var tracker = helper.componentTracker.trackComponent(config.componentDef.descriptor);
            $A.componentService.newComponentAsync(
                this,
                function(innerComponent) {
                    tracker.complete();
                    cmp.set('v.body', innerComponent);
                },
                config,
                cmp
            )    ;
        } catch (e) {
            var errorMsg = $A.util.format($A.get('$Label.ComponentInstance.LightningComponentProblem'), e.message, config.componentDef.descriptor);
            $A.reportError(errorMsg, e);
        }
    },
    "evaluateExpressionAttributesAndInstantiate":function(cmp, isRefresh) {
        var helper = this;
        var context = cmp.get('v.context');


        var ruleAttributeIndices = {};
        var ruleAttributeFields = {};
        var attributesList = [];
        var cdr = helper.getComponentInfoDefRef(cmp) || [];

        var expressionMap = {};
        var componentContext = cmp.get("v.componentContext");
        var componentInfo = cdr[0];
        if(componentInfo) {
            expressionMap = helper.getExpressionsFromFacet(cmp, attributesList);
        }
        if (componentContext && componentContext.expressionMap) {
            var componentExpressionMap = componentContext.expressionMap;
            for (var expression in componentExpressionMap) {
                expressionMap[expression] = componentExpressionMap[expression];
            }
        }
        if(context && context.expressionService) {
            var componentAttributes = componentInfo.attributes.values;
            for(var attribute in componentAttributes) {
                if(componentAttributes.hasOwnProperty(attribute)) {
                    attributesList[attribute] = componentAttributes[attribute];
                }
            }


            for(var attribute in expressionMap) {
                if(expressionMap.hasOwnProperty(attribute)) {
                    var expressionEvalResult = expressionMap[attribute];
                    if(expressionEvalResult) {
                        if(expressionEvalResult.expressionEvalStatus ===
                            context.expressionService.expressionServerEvalCode.GENERATED_JAVASCRIPT){
                            if(ruleAttributeIndices[expressionEvalResult.expressionEvalValue]){
                                ruleAttributeIndices[expressionEvalResult.expressionEvalValue].push(attribute);
                            }else{
                                ruleAttributeIndices[expressionEvalResult.expressionEvalValue] = [attribute];
                            }
                            ruleAttributeFields[expressionEvalResult.expressionEvalValue] = expressionEvalResult.expressionFields;
                        } else {
                            $A.log("Error while constructing component", expressionEvalResult.expressionEvalValue);
                            return;
                        }
                    }
                }
            }
        }

        var scripts = Object.keys(ruleAttributeIndices);
        if(scripts.length > 0) {

            var i = scripts.length;
            var fieldsJson = {};
            try {
                while(i--){
                    var scriptFields = context.expressionService.getFieldsForExpression(ruleAttributeFields[scripts[i]]);
                    var contexts = Object.keys(scriptFields);
                    var j = contexts.length;
                    while(j--){
                        var contextName = contexts[j];
                        if(fieldsJson[contextName]){
                            fieldsJson[contextName].push.apply(fieldsJson[contextName], scriptFields[contextName]);
                        }else{
                            fieldsJson[contextName] = scriptFields[contextName];
                        }
                    }
                }
            } catch(e) {
                $A.log("Error while constructing component", e);
                return;
            }

            context.expressionService.getContexts(fieldsJson).then($A.getCallback(function(context) {
                if (!cmp.isValid()){
                    return;
                }
                var i = scripts.length;
                var j = 0;
                var success = true;
                var cdrInner = helper.getComponentInfoDefRef(cmp) || [];
                try{
                    while(i--){
                        for(j = 0; j < ruleAttributeIndices[scripts[i]].length; j++) {


                            var attributeName = ruleAttributeIndices[scripts[i]][j];
                            attributesList[attributeName].value = helper.formula.evaluation.evaluate(scripts[i], context, 'EXPRESSIONS');
                        }
                    }
                }catch(e){
                    success = false;
                    $A.log("Error while constructing component", e);
                    return;
                }
                if(success){
                    helper.initialize(cmp, isRefresh);
                }
            }), $A.getCallback(function(err) {

                $A.log("Issue contexts for expression evaluation", err.error);
            })).catch($A.getCallback(function(err) {
                $A.log("Error while constructing component", err);
                return;
            }));
        }else{
            helper.initialize(cmp, isRefresh);
        }
    },
    "evaluateComponentRule":function(cmp, isRefresh) {
        var body = cmp.get('v.body') || [];
        var helper = this;
        var componentInfoDefRef = helper.getComponentInfoDefRef(cmp) || [];
        var rule;
        var facetRule;
        var rulesOnFacets;
        var isPhone = $A.get('$Browser.isPhone');
        var facetName;

        var componentContext = cmp.get('v.componentContext');
        if (componentContext) {
            rule = componentContext.rule;
            facetRule = componentContext.facetRules;

            if(facetRule && componentContext.facet && isPhone) {
                facetName = componentContext.facet[0];
                rulesOnFacets = facetRule[facetName];
            }
        }

        var context = cmp.get('v.context');






        if ((rulesOnFacets || !!rule) && context && context.expressionService ) {
            var recordFields = cmp.get('v._fields');
            var fieldsMap = {};
            if(rule) {
                fieldsMap = rule.fieldsMap;
            }

            if(rulesOnFacets && isPhone) {
                Object.keys(rulesOnFacets).forEach(function (facetIndex) {
                   var facetRule = rulesOnFacets[facetIndex];
                   Object.assign(fieldsMap, facetRule.fieldsMap);
                });
            }

            if (!recordFields || recordFields.length === 0) {


                var fields = context.expressionService.getFieldsForExpression(Object.keys(fieldsMap));
                setTimeout($A.getCallback(function() {
                    if(fields.record) {
                        cmp.set('v._fields', fields.record);
                    }
                }), 0);
            }

            context.expressionService.getEvaluatedContexts(fieldsMap)
                .then($A.getCallback(function(context) {
                    if (!cmp.isValid()){
                        return;
                    }
                    var shouldRender = false;
                    if(rule) {
                        shouldRender = helper.evaluateRule(rule, context)
                    } else {
                        shouldRender = true;
                    }
                    if(shouldRender === true) {
                        if(rulesOnFacets && Object.keys(rulesOnFacets).length !== 0 && facetName && isPhone) {
                            var componentInfo = componentInfoDefRef[0];
                            var areFacetVisibilitiesUpdated = false;
                            var facetVisibility = [];

                            Object.keys(rulesOnFacets).forEach(function(facetIndex) {

                                if(componentInfo && componentInfo.attributes) {
                                    var componentAttributes = componentInfo.attributes.values;

                                    if (componentAttributes[facetName] && componentAttributes[facetName].value) {
                                        var currentFacetComponents = componentAttributes[facetName].value; 
                                        var facetRule = rulesOnFacets[facetIndex]; 
                                        var shouldRenderFacet = helper.evaluateRule(facetRule, context)
                                        var previousValue = currentFacetComponents[facetIndex].attributes.values.hidden;

                                        facetVisibility[facetIndex] = shouldRenderFacet;
                                        var isCurrentFacetHidden;

                                        if (!shouldRenderFacet) {
                                            currentFacetComponents[facetIndex].attributes.values.hidden = {
                                                "descriptor": "hidden",
                                                "value": true
                                            };
                                            isCurrentFacetHidden = true;
                                        } else {
                                            currentFacetComponents[facetIndex].attributes.values.hidden = {
                                                "descriptor": "hidden",
                                                "value": false
                                            };
                                            isCurrentFacetHidden = false;
                                        }
                                        if (previousValue !== isCurrentFacetHidden) {
                                            areFacetVisibilitiesUpdated = true;
                                        }
                                    }
                                }
                            });
                            var bodyInner = cmp.get('v.body') || [];
                            if (isRefresh || bodyInner.length === 0) {
                                helper.evaluatePropertyListItemRulesAndInstantiate(cmp, isRefresh);
                            } else {
                                if (areFacetVisibilitiesUpdated) {
                                    var component = cmp.get('v.body')[0];
                                    if(component && component.type === 'flexipage:tabset')
                                        component.updateFacetVisibility(facetVisibility);
                                }
                            }
                        }
                        else {
                            var bodyInner = cmp.get('v.body') || [];
                            if (isRefresh || bodyInner.length === 0) {
                                helper.evaluatePropertyListItemRulesAndInstantiate(cmp, isRefresh);
                            }
                        }
                    } else {
                        cmp.set('v.body', []);
                    }
                }), $A.getCallback(function(err) {

                    $A.log("Issue fetching record for rule evaluation", err.error);
                })).catch($A.getCallback(function(err) {
                $A.error("Error while constructing component", err);
            }));
        } else {

            helper.evaluatePropertyListItemRulesAndInstantiate(cmp, isRefresh);
        }
    },
    "evaluateRule":function(rule, context) {
        var helper = this;
        var shouldRender = false;
        try {
            shouldRender = helper.formula.evaluation.evaluate(rule.javascriptRule, context, 'EXPRESSIONS');
        } catch (e) {


            $A.warning("Issue while evaluating component rule", e);
        }
        return shouldRender;
    },
    "evaluatePropertyListItemRulesAndInstantiate":function(cmp, isRefresh) {
        var listItemsRulesMap;
        var helper = this;
        var componentInfoDefRef = helper.getComponentInfoDefRef(cmp) || [];
        helper._promises = [];
        var propertyValueFilters = {};
        var propertyValuesMap;
        if (componentInfoDefRef.length !== 0) {
            var componentContext = cmp.get('v.componentContext');
            if (componentContext) {
                listItemsRulesMap = componentContext.listItemsRulesMap;
                propertyValuesMap = componentContext.propertyValuesMap;
            }
        }


        if (listItemsRulesMap) {
            var listItemsRulesMapKeys = Object.keys(listItemsRulesMap);

            Object.keys(listItemsRulesMapKeys).forEach(function(key) {
                var propertyName = listItemsRulesMapKeys[key];
                var context = cmp.get('v.context');

                if (context && context.expressionService && listItemsRulesMap[propertyName] !== null && listItemsRulesMap[propertyName] instanceof Array) {
                    listItemsRulesMap[propertyName].forEach(function(ruleInfo, i){
                        var rule =  ruleInfo;
                        var index = rule[0];
                        var ruleDetails = rule[1];
                        var fieldsMap = ruleDetails.fieldsMap;

                        var recordFields = cmp.get('v._fields');

                        if (!recordFields || recordFields.length === 0) {


                            var fields = context.expressionService.getFieldsForExpression(Object.keys(fieldsMap));
                            setTimeout($A.getCallback(function() {
                                if(fields.record) {
                                    cmp.set('v._fields', fields.record);
                                }
                            }), 0);
                        }

                        helper._promises.push(
                            context.expressionService.getEvaluatedContexts(fieldsMap)
                                .then($A.getCallback(function(innerContext) {
                                    var shouldRender = false;
                                    try {
                                        shouldRender = helper.formula.evaluation.evaluate(ruleDetails.javascriptRule, innerContext, 'EXPRESSIONS');
                                    } catch (e) {


                                        $A.warning("Issue while evaluating list item rule", e);
                                    }

                                    if (shouldRender === false) {
                                        if (!propertyValueFilters[propertyName]) {
                                            propertyValueFilters[propertyName] = [];
                                        }
                                        propertyValueFilters[propertyName].push(index);
                                    }
                                }), $A.getCallback(function(err) {

                                    $A.log("Issue fetching record for rule evaluation", err.error);
                                }))
                        );
                    });
                }
            });

            Promise.all(helper._promises).then($A.getCallback(function() {


                if (propertyValueFilters) {
                    var componentInfo = componentInfoDefRef[0];

                    if (componentInfo) {
                        var componentAttributesValues = componentInfo.attributes.values;


                        var propertyNames = Object.keys(propertyValuesMap);

                        propertyNames.forEach( function(propertyValueName) {


                            var initialPropertyValues = JSON.parse(JSON.stringify(propertyValuesMap[propertyValueName]));



                            if (propertyValueFilters.hasOwnProperty(propertyValueName) && propertyValueFilters[propertyValueName] instanceof Array) {
                                propertyValueFilters[propertyValueName].sort(function(a, b) {
                                    return a - b;
                                });


                                for (var i = propertyValueFilters[propertyValueName].length - 1; i >= 0; i--) {
                                    initialPropertyValues.splice(propertyValueFilters[propertyValueName][i] , 1);
                                }
                            }


                            if (JSON.stringify(initialPropertyValues) === JSON.stringify(componentAttributesValues[propertyValueName].value)) {
                                cmp.set('v.updateComponentContent', false);
                            } else {

                                var body = cmp.get('v.body');
                                if (body && body[0]) {
                                    var component = body[0];
                                    if(component && component.attributes) {
                                        component.attributes[propertyValueName] = initialPropertyValues;
                                        cmp.set('v.body', body);
                                    }
                                }
                                componentAttributesValues[propertyValueName].value = initialPropertyValues;
                                cmp.set('v.updateComponentContent', true);
                            }
                        });
                    }
                }


                helper.evaluateExpressionAttributesAndInstantiate(cmp, isRefresh);

            }), $A.getCallback(function(err) {

                $A.log("Issue with visibility rule evaluation", err);
            }));
        }


        else {
            helper.evaluateExpressionAttributesAndInstantiate(cmp, isRefresh);
        }


    },
    "refresh":function(cmp, infoOfComponent) {
        var helper = this;
        var component = cmp.get('v.body')[0];
        var shouldSimulateContentRefresh = component.isInstanceOf('one:simulateContentRefresh');
        var handlesRefresh = component.isInstanceOf('ui:handlesRefresh') && component.get('v.canRefresh') !== false;
        if (handlesRefresh && !shouldSimulateContentRefresh){
            var refreshAction = component.get("e.refresh");
            if (refreshAction){
                refreshAction.setComponentEvent(); 
                refreshAction.fire();
            }
        } else if (shouldSimulateContentRefresh) {
            helper.createConcreteComponent(cmp, infoOfComponent);
        }
    },
    "getExpressionsFromFacet":function(cmp, attributesList) {
        var expressionMap = [];
        var componentInfo = this.getComponentInfoDefRef(cmp)[0];
        var componentAttributes = componentInfo.attributes.values;
        if(cmp.get("v.componentContext") && cmp.get("v.componentContext").facet) {

            var facetNames = cmp.get("v.componentContext").facet;
            facetNames.forEach(function(facetName) {
                if(componentAttributes[facetName] && componentAttributes[facetName].value) {

                    var facetComponents = componentAttributes[facetName].value;
                    facetComponents.forEach(function(facetComponent, index) {
                        var attributes = facetComponent.attributes.values;
                        var attributeIndex = attributesList.length;


                        for (var attribute in attributes) {
                            if(attributes.hasOwnProperty(attribute)) {
                                if(attributes[attribute].value.expressionEvalStatus) {
                                    attributesList[attributeIndex] = attributes[attribute];
                                    expressionMap[attributeIndex] = attributes[attribute].value;
                                    attributeIndex++;
                                }
                            }
                        }
                    });
                }
            });
        }
        return expressionMap;
    },
    "getComponentInfoDefRef":function(cmp) {
        return cmp.get('v._localComponentInfoDefRef');
    }
  }
};
});
